def get_perimeter(n):
    # For a diamond of radius n (cells (x,y) s.t. |x|+|y| <= n)
    # The boundary is the set of edges with one endpoint in the diamond and one outside.
    # Let's compute this for small n.
    cells = []
    for x in range(-n, n + 1):
        for y in range(-n, n + 1):
            if abs(x) + abs(y) <= n:
                cells.append((x, y))

    edges = set()
    for (x, y) in cells:
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if abs(nx) + abs(ny) > n:
                # Edge between (x, y) and (nx, ny)
                edge = tuple(sorted([(x, y), (nx, ny)]))
                edges.add(edge)
    return len(edges)

for n in range(5):
    print(f"n={n}, perimeter={get_perimeter(n)}")

def get_perimeter_correct(n):
    cells = set()
    for x in range(-n, n + 1):
        for y in range(-n, n + 1):
            if abs(x) + abs(y) <= n:
                cells.add((x, y))

    perimeter_edges = set()
    for (x, y) in cells:
        # The 4 edges of cell (x,y)
        edges = [
            tuple(sorted([(x, y), (x + 1, y)])),
            tuple(sorted([(x + 1, y), (x + 1, y + 1)])),
            tuple(sorted([(x + 1, y + 1), (x, y + 1)])),
            tuple(sorted([(x, y + 1), (x, y)])),
        ]
        for e in edges:
            # An edge is on the perimeter if it's shared by one cell in 'cells' and one not in 'cells'
            # To find the other cell sharing the edge:
            v1, v2 = e
            # The two cells sharing edge {(x,y), (x+1,y)} are (x,y) and (x,y-1)
            if v1 == (x, y) and v2 == (x + 1, y):
                other = (x, y - 1)
            elif v1 == (x + 1, y) and v2 == (x + 1, y + 1):
                other = (x + 1, y)
            elif v1 == (x, y + 1) and v2 == (x + 1, y + 1):
                other = (x, y + 1)
            elif v1 == (x, y) and v2 == (x, y + 1):
                other = (x - 1, y)
            else:
                continue

            if other not in cells:
                perimeter_edges.add(e)
    return len(perimeter_edges)

for n in range(5):
    print(f"n={n}, perimeter={get_perimeter_correct(n)}")
